/**
 * Generates packages/fsapi-core/src/generated/nodes.ts from data/node-catalog.json.
 *
 * Usage: pnpm gen          (write)
 *        pnpm gen:check    (exit 1 if the generated file is stale)
 */
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import type { CuratedCatalog, CuratedNode } from "./curate-catalog.ts";

const CATALOG = resolve("data/node-catalog.json");
const TARGET = resolve("packages/fsapi-core/src/generated/nodes.ts");

function key(name: string): string {
  return /^[A-Za-z_$][\w$]*$/.test(name) ? name : JSON.stringify(name);
}

function renderNode(node: CuratedNode): string {
  const parts = [
    `type: ${JSON.stringify(node.type)}`,
    `readOnly: ${node.readOnly}`,
    `notifying: ${node.notifying}`,
    `cacheable: ${node.cacheable}`,
    `address: 0x${node.address.toString(16)}`,
    `registered: ${node.registered}`,
  ];
  if (node.maxLength !== undefined) parts.push(`maxLength: ${node.maxLength}`);
  if (node.min !== undefined) parts.push(`min: ${node.min}`);
  if (node.max !== undefined) parts.push(`max: ${node.max}`);
  if (node.enum) {
    const entries = node.enum.map(({ name, value }) => `${key(name)}: ${value}`).join(", ");
    parts.push(`enum: { ${entries} }`);
  }
  if (node.fields) {
    const fields = node.fields
      .map(
        (f) =>
          `{ name: ${JSON.stringify(f.name)}, type: ${JSON.stringify(f.type)}, length: ${f.length} }`,
      )
      .join(", ");
    parts.push(`fields: [${fields}]`);
  }
  return `  ${JSON.stringify(node.path)}: { ${parts.join(", ")} },`;
}

const catalog = JSON.parse(readFileSync(CATALOG, "utf8")) as CuratedCatalog;
const source = [
  "// GENERATED by tools/gen-nodes.ts from data/node-catalog.json. Do not edit.",
  `// Source: ${catalog.source.app} ${catalog.source.version} (static analysis), ${catalog.nodes.length} nodes.`,
  'import type { NodeDef } from "../types.ts";',
  "",
  "export const NODE_DEFS = {",
  ...catalog.nodes.map(renderNode),
  "} as const satisfies Record<string, NodeDef>;",
  "",
].join("\n");

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(TARGET, "utf8");
  } catch {
    // Missing file counts as stale.
  }
  if (current !== source) {
    console.error(`${TARGET} is stale; run \`pnpm gen\`.`);
    process.exit(1);
  }
  console.log("Generated nodes are up to date.");
} else {
  writeFileSync(TARGET, source);
  console.log(`Wrote ${catalog.nodes.length} node definitions to ${TARGET}`);
}
